INSERT INTO "public"."votaciones" ("id", "type", "title", "foundation_name", "impact_area", "hc_reward", "votes_count", "votes_goal", "ends_at", "created_at", "description", "image_url") VALUES ('31ab0ab8-f1ca-451c-93f5-72e242bec2cf', 'Ahorro', 'Cajas de ahorro para mujeres emprendedoras', 'Impulso Rosa', 'Pobreza', 300, 91, 300, '2026-07-07 17:44:58.473038+00', '2026-07-01 17:44:58.473038+00', 'Fondo rotativo que otorga cajas de ahorro y microcréditos a mujeres que buscan iniciar o hacer crecer un negocio propio, con acompañamiento financiero básico incluido.', null), ('8264d988-dae6-4841-aab3-998164102818', 'Crowdfunding', 'Reforestación de la sierra', 'EcoFuturo A.C.', 'Medio ambiente', 650, 411, 450, '2026-07-03 17:44:58.473038+00', '2026-06-23 17:44:58.473038+00', 'Proyecto de reforestación con especies nativas en zonas afectadas por incendios forestales. Busca restaurar el ecosistema y capacitar a brigadas comunitarias en el cuidado de los nuevos árboles.', null), ('bb079ba3-64c0-4068-b347-982ab82eda23', 'Social', 'Bibliotecas comunitarias', 'Fundación Leer es Crecer', 'Educación', 450, 461, 500, '2026-07-03 05:44:58.473038+00', '2026-06-28 17:44:58.473038+00', 'Instalación de bibliotecas comunitarias con acceso gratuito a libros y actividades de fomento a la lectura para niñas y niños en zonas con poca oferta educativa.', null), ('e9861e14-2f75-476c-b8d3-b6ba9da848f6', 'Voluntariado', 'Brigadas médicas móviles', 'Cruz Verde A.C.', 'Salud', 800, 121, 400, '2026-07-12 17:44:58.473038+00', '2026-06-30 17:44:58.473038+00', 'Unidades médicas móviles que llevan consultas, medicamentos básicos y campañas de vacunación a comunidades sin acceso regular a servicios de salud. Cada voto ayuda a financiar una jornada adicional de atención.', null), ('fd96c836-90c9-4117-a200-c733a8a9b504', 'Social', 'Comedores comunitarios en zonas rurales', 'Fundación Honoris Causa', 'Pobreza', 500, 341, 500, '2026-07-04 17:44:58.473038+00', '2026-06-26 17:44:58.473038+00', 'Esta iniciativa busca llevar comedores comunitarios a zonas rurales con alta marginación, garantizando al menos una comida completa al día para niñas, niños y adultos mayores. Los fondos y votos recaudados se destinan a la compra de insumos y al mantenimiento de la infraestructura.', null);